    "note": "真上視点。中心へ光を集め、白熱した核を形成。交差する大小2つの衝撃波・爆炎・閃光を同時に3回放つ。大きい衝撃波の向きを各回で交互に入れ替える。 前の爆炎と衝撃波が拡大している最中に次の爆発を発生させ、三波を重ねる。",
    "body": "if(q<=0.||q>=1.)return vec4(0.);\nfloat g=phase(q,0.,.36);vec4 v=fc(p,vec2(0.),q,.36,.70);\nvec4 w=fm(p,vec2(0.),(.045+.19*g)*(1.+.055*sin(t*TAU*12.)),t,71.);w.a*=gate(q,0.,.40);v=over(v,w);\n// Each blast expands independently; launch the next while earlier waves are still expanding.\nfor(int i=0;i<3;i++){\n float k=float(i),start=.36+k*.10,f=phase(q,start,start+.44);\n if(f>0.&&f<1.){\n  v=over(v,denseBurst(p,vec2(0.),f,.76,t,k+80.));\n  float flash=(1.-smoothstep(.10,.88,length(p)/max(.025,.58*fq(f))))*gate(f,0.,.32);\n  v=over(v,vec4(1.,.97,.84,flash*.92));\n }\n}\n// Composite all expanding shock fronts above the fire so older waves remain visible.\nfor(int i=0;i<3;i++){\n float k=float(i),start=.36+k*.10,f=phase(q,start,start+.44);\n if(f>0.&&f<1.){\n  float ang=.68,alt=mod(k,2.);\n  vec2 p1=vec2(p.x*cos(ang)-p.y*sin(ang),p.x*sin(ang)+p.y*cos(ang));\n  vec2 p2=vec2(p.x*cos(ang)+p.y*sin(ang),-p.x*sin(ang)+p.y*cos(ang));\n  v=over(v,fp(p1,vec2(0.),f,mix(.96,.57,alt),.38));\n  v=over(v,fp(p2,vec2(0.),f,mix(.57,.96,alt),.38));\n }\n}\nreturn v;\n"
