    "body": "float wind=.72+.28*sin(t*TAU);vec4 v=vec4(0.);for(int i=0;i<6;i++){float k=float(i),a=t*TAU+k*TAU/6.;vec2 c=weatherCenter(vec2(cos(a)*.49,.50+sin(a)*.13),t,q,k);vec4 w=coldMist(p,c,vec2(.38,.22),sin(t*TAU)*.7,k);w.a*=weatherAlpha(q,k);v=over(v,w);}vec4 m=coldMist(p,vec2(.15*sin(t*TAU),-.12),vec2(.81,.50),sin(t*TAU)*.7,7.);m.a*=(.60+.28*wind)*weatherWeather(q);v=over(v,m);vec4 snow=snowField(vec2(p.x,p.y*1.45+.26),t*2.,.75+.25*wind,.65,27.,.029);snow.a*=weatherWeather(q);return over(v,snow);"
