    "body": "float time=t*TAU;vec4 v=vec4(0.);for(int i=0;i<12;i++){float k=float(i),a=time*2.+k*.62,r=.18+.052*k;vec2 c=weatherCenter(dir2(a)*vec2(r,r*.40)+vec2(0.,.40),t,q,k*.50);vec4 w=coldMist(p,c,vec2(.28,.17),sin(time)*.45,k);w.a*=.80*weatherAlpha(q,k*.50);v=over(v,w);}vec4 snow=snowField(vec2(p.x,p.y*1.45+.26),t*2.,.90,.43,26.,.032);snow.a*=weatherWeather(q);return over(v,snow);"
