    "body": "float g=rush(phase(q,.34,.66)),e=wetEnv(q,.25,.82);vec4 v=wetCharge(p,vec2(0.),q,.52);vec4 w=horizontalWhirl(p,t*1.7,g,.79,e);v=over(v,w);return over(v,droplets(p,vec2(0.),phase(q,.46,1.),.63,8.,18.));"
